rule.definition:
a!localVariables(
  local!names:#"SYSTEM_SYSRULES_queryRecordType_v3"(
    recordType: #"urn:appian:record-type:v1:bc5e6a76-7744-4085-b06e-7d720168e945",
    fields: #"SYSTEM_SYSRULES_selectionFields"(
      allFieldsFromRecordType: #"urn:appian:record-type:v1:bc5e6a76-7744-4085-b06e-7d720168e945"
    ),
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
        field: #"urn:appian:record-field:v1:bc5e6a76-7744-4085-b06e-7d720168e945/727b739d-327a-4d16-8462-497c000d0476",
        operator: "in",
        value: ri!stateId
      ),
      #"SYSTEM_SYSRULES_queryFilter"(
        field: #"urn:appian:record-field:v1:bc5e6a76-7744-4085-b06e-7d720168e945/8c437579-47f2-4deb-8a15-276c6deee304",
        operator: "in",
        value: ri!countryId
      ),
      #"SYSTEM_SYSRULES_queryFilter"(
        field: #"urn:appian:record-field:v1:bc5e6a76-7744-4085-b06e-7d720168e945/4395816f-d90e-4d55-939e-2cddaa7c8ee5",
        operator: "=",
        value: ri!isActive
      )
      },
      ignoreFiltersWithEmptyValues: true(),
    )
    ,
    pagingInfo: a!defaultValue(
      value: ri!paginginfo,
      default:  #"SYSTEM_SYSRULES_pagingInfo"(
        startIndex: 1,
        batchSize: 5000
      )
    )
  ),
  local!data:index(local!names,"data",null()),
  {
    local!data
  }
)
